#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    int len;
    string s;
    cin >> len >> s;

    int maxOutside = 0;
    int wordsInside = 0;
    int currentLength = 0;
    bool inside = false;

    for (char c : s) {
        if (c == '(') {
            maxOutside = max(maxOutside, currentLength);
            currentLength = 0;
            inside = true;
        } else if (c == ')') {
            if (currentLength > 0) {
                ++wordsInside;
            }
            currentLength = 0;
            inside = false;
        } else if (c == '_') {
            if (currentLength > 0) {
                if (inside) {
                    ++wordsInside;
                } else {
                    maxOutside = max(maxOutside, currentLength);
                }
            }
            currentLength = 0;
        } else {
            ++currentLength;
        }
    }

    if (currentLength > 0) {
        if (inside) {
            ++wordsInside;
        } else {
            maxOutside = max(maxOutside, currentLength);
        }
    }

    cout << maxOutside << ' ' << wordsInside;
    return 0;
}

